<script setup lang="ts">import{computed,onMounted}from'vue';import{useRoute}from'vue-router';import{useAuthStore}from'./stores/auth';const route=useRoute(),auth=useAuthStore(),title=computed(()=>route.meta.title||'Career Orbit');const nav=[['/','House','首页'],['/resumes','Document','我的简历'],['/optimize','MagicStick','简历优化'],['/questions','List','面试题生成'],['/interview','ChatDotRound','模拟面试'],['/records','Clock','面试记录'],['/profile','User','个人中心']];onMounted(()=>{if(auth.authenticated&&!auth.user)auth.loadUser().catch(()=>auth.logout())})</script>
<template><router-view v-if="route.meta.public"/><div v-else class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">CO</div><div class="brand-copy"><b>CAREER ORBIT</b><small>真实 AI 求职训练</small></div></div><nav class="main-nav"><router-link v-for="n in nav" :key="String(n[0])" :to="String(n[0])"><el-icon><component :is="n[1]"/></el-icon><span><b>{{n[2]}}</b></span><i/></router-link><router-link v-if="auth.isAdmin" to="/admin"><el-icon><Setting/></el-icon><span><b>管理控制台</b></span><i/></router-link></nav><div class="user-panel"><div class="avatar">{{auth.user?.displayName?.slice(0,1)||'U'}}</div><span><b>{{auth.user?.displayName||'加载中'}}</b><small>{{auth.user?.email}}</small></span><el-icon title="退出登录" @click="auth.logout"><SwitchButton/></el-icon></div></aside><section class="main-area"><header class="topbar"><div><div class="eyebrow">CAREER COMMAND CENTER</div><h1>{{title}}</h1></div><router-link to="/questions" class="primary-button"><el-icon><Plus/></el-icon> 生成面试题</router-link></header><main><router-view/></main></section></div></template>
